\title{Towards precision cosmology with Voids $\times$ CMB correlations (I)}
\subtitle{{\emph{Roman}-\textsc{Agora}} mock catalogs and pipeline validation}

\titlerunning{Towards precision cosmology with Roman Void $\times$ CMB correlations}
